export function evaluate({ inputs, time }) {
  const u = inputs.launchSpeed, g = inputs.gravity, m = inputs.mass;
  const T = 2 * u / g, ta = u / g;
  const t = sdk.clamp(time, 0, T);
  const v = u - g * t;
  const y = Math.max(0, u * t - g * t * t / 2);
  const F = m * g;
  const hTop = u * u / (2 * g);
  let st = 'Rising';
  if (time <= 0) st = 'Ready to toss';
  else if (time >= T - 1e-9) st = 'Back at launch height';
  else if (Math.abs(t - ta) < 0.005) st = 'At the top';
  else if (t > ta) st = 'Falling';
  const o = [];
  o.push(...sdk.panel({ id: 'lane.motion', x: 10, y: 34, w: 305, h: 376, title: 'The motion', state: st }));
  o.push(...sdk.panel({ id: 'lane.graph', x: 325, y: 34, w: 305, h: 376, title: 'Velocity over time', state: 'a = -g' }));
  o.push(sdk.axis('axis.h', { x: 90, y: 360, length: 270, orientation: 'y', min: 0, max: 2.2, ticks: [0, 0.5, 1, 1.5, 2], label: 'Height', unit: 'm' }));
  const py = sdk.linear([0, 2.2], [360, 90]);
  const by = py(y);
  o.push(sdk.circle('ball.toss', 170, by, 26));
  o.push(...sdk.vector('vec.v', { x: 170, y: by - 20 }, { value: v, direction: 'up' }, { scale: 8, label: 'v', role: 'observed' }));
  o.push(...sdk.vector('vec.a', { x: 205, y: by }, { value: -g, direction: 'up' }, { scale: 5, label: 'a', role: 'warning' }));
  o.push(...sdk.callout(225, 120, ['v = ' + sdk.format(v, 2) + ' m/s', 'a = ' + sdk.format(-g, 1) + ' m/s^2', 'Fg = ' + sdk.format(F, 1) + ' N'], { id: 'callout.toss' }));
  const pts = [];
  const n = 12;
  for (let i = 0; i <= n; i++) { const tt = 1.8 * i / n; pts.push({ x: tt, y: sdk.clamp(u - g * tt, -5.5, 5.5) }); }
  o.push(sdk.plot('plot.vt', { x: 345, y: 70, w: 275, h: 290, axes: { x: { label: 'Time', min: 0, max: 1.8, unit: 's' }, y: { label: 'v', min: -5.5, max: 5.5, unit: 'm/s' } }, series: [{ label: 'v = u - g t', kind: 'line', points: pts }, { label: 'now', kind: 'scatter', points: [{ x: t, y: sdk.clamp(v, -5.5, 5.5) }] }] }));
  o.push(sdk.text('plot.vt.note', 480, 392, 'slope a = -g', { role: 'warning' }));
  return { frame: { width: 640, height: 420, objects: o, readouts: [{ id: 'velocity', value: v }, { id: 'acceleration', value: -g }, { id: 'force', value: F }, { id: 'motionState', value: st }] }, quantities: { launchSpeed: u, gravity: g, mass: m, apexTime: ta, apexHeight: hTop, height: y, velocity: v, acceleration: -g, force: F } };
}
